CREATE SCHEMA IF NOT EXISTS casa_mia;
SET search_path TO casa_mia;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bookings(id TEXT PRIMARY KEY,checkin TEXT NOT NULL,checkout TEXT NOT NULL,guests INTEGER NOT NULL CHECK(guests BETWEEN 1 AND 4),name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'direct',total INTEGER NOT NULL CHECK(total>=0),due INTEGER NOT NULL CHECK(due>=0),payment TEXT NOT NULL,status TEXT NOT NULL,created TEXT NOT NULL,expires BIGINT,stripe_session TEXT,idempotency TEXT UNIQUE NOT NULL,CHECK(checkout>checkin));
CREATE TABLE IF NOT EXISTS nights(date TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS bookings_status ON bookings(status);
CREATE INDEX IF NOT EXISTS bookings_dates ON bookings(checkin,checkout);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
